#ifndef MUNINN_BIGRAMS
#define MUNINN_BIGRAMS
/*
 * Hashed character bigrams of a command line (muninn_ref.text): lowercase, whitespace
 * runs as one space, '^' before and '$' after the line; each adjacent pair (a, b) sets
 * bit (31 * a + b) % features of bits[] ((features + 31) / 32 words).
 */
static inline void muninn_bigram_set(unsigned int *bits, unsigned int features,
				     unsigned int a, unsigned int b)
{
	unsigned int h = (31 * a + b) % features;

	bits[h / 32] |= 1u << (h % 32);
}

static inline void muninn_bigrams(const char *line, unsigned int features,
				  unsigned int *bits)
{
	unsigned int prev = '^', space = 0, c, i;

	for (i = 0; i < (features + 31) / 32; i++)
		bits[i] = 0;
	for (; *line; line++) {
		c = (unsigned char)*line;
		if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
			space = prev != '^';
			continue;
		}
		if (c >= 0x80)
			c = '?';
		if (c >= 'A' && c <= 'Z')
			c += 'a' - 'A';
		if (space) {
			muninn_bigram_set(bits, features, prev, ' ');
			prev = ' ';
			space = 0;
		}
		muninn_bigram_set(bits, features, prev, c);
		prev = c;
	}
	muninn_bigram_set(bits, features, prev, '$');
}
#endif

